-- Gen4 pokemon (run after gen3 seeds). Regenerated by scripts/generate-gen4-pokemon-seed.mjs

-- Abilities used by Gen4-era species (skip existing ids; full rows come from gen4_abilities.sql)
on conflict (id) do nothing;

-- Gen4 Sinnoh species (dex 387–493) + alternate forms. Additive UPSERT.
on conflict (dex_no, region_type, is_mega, name_en, available_generations) do update set
  name_ja = excluded.name_ja,
  category = excluded.category,
  introduced_generation = excluded.introduced_generation,
  type1 = excluded.type1,
  type2 = excluded.type2,
  base_hp = excluded.base_hp,
  base_attack = excluded.base_attack,
  base_defense = excluded.base_defense,
  base_special = excluded.base_special,
  base_sp_attack = excluded.base_sp_attack,
  base_sp_defense = excluded.base_sp_defense,
  base_speed = excluded.base_speed,
  ability1_id = excluded.ability1_id,
  ability2_id = excluded.ability2_id,
  hidden_ability_id = excluded.hidden_ability_id,
  gender = excluded.gender,
  is_final_evolution = excluded.is_final_evolution,
  sprite_url = excluded.sprite_url;

-- Gen1–3 species that gain an evolution in Gen4: keep the Gen1–3 row final,
-- add a Gen4+ copy with is_final_evolution = false. Idempotent.
select p.dex_no, p.region_type, p.name_ja, p.name_en, p.category, p.introduced_generation, p.available_generations & ~7, p.type1, p.type2, p.base_hp, p.base_attack, p.base_defense, p.base_special, p.base_sp_attack, p.base_sp_defense, p.base_speed, p.ability1_id, p.ability2_id, p.hidden_ability_id, p.gender, p.is_mega, false, p.sprite_url
from moshimo.pokemon p
where p.dex_no in (82, 108, 112, 114, 125, 126, 133, 176, 190, 193, 198, 200, 207, 215, 221, 233, 281, 299, 315, 356, 361)
  and p.is_final_evolution
  and (p.available_generations & 8) <> 0
  and (p.available_generations & 7) <> 0
on conflict (dex_no, region_type, is_mega, name_en, available_generations) do nothing;

update moshimo.pokemon p
set available_generations = p.available_generations & 7
where p.dex_no in (82, 108, 112, 114, 125, 126, 133, 176, 190, 193, 198, 200, 207, 215, 221, 233, 281, 299, 315, 356, 361)
  and p.is_final_evolution
  and (p.available_generations & 8) <> 0
  and (p.available_generations & 7) <> 0;
